INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(80040886, 'Navy Dragon Mech', '碧钢机龙', '碧鋼の機竜', 'Synchro Monster', 'Machine', 'WATER', 9, 2700, 1800, '调整＋调整以外的怪兽1只以上 ①：这张卡特殊召唤成功的场合，以最多有自己墓地的调整数量的对方场上的表侧表示的卡为对象才能发动。那些卡的效果直到回合结束时无效。 ②：同调召唤的这张卡被效果破坏送去墓地的场合，以自己墓地1只调整为对象才能发动。那只怪兽加入手卡。'),
(41525660, 'Nazuki the Vaylantz Ninja', '弈勇之忍者－南月', 'ヴァリアンツの忍者－南月', 'Pendulum Effect Monster', 'Spellcaster', 'WATER', 6, 1800, 1800, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：以这张卡以外的主要怪兽区域1只怪兽为对象才能发动。那只怪兽的位置向那个相邻的怪兽区域移动。 ②：怪兽区域的这张卡向其他的怪兽区域移动的场合，以自己的魔法与陷阱区域1张「群豪」怪兽卡为对象才能发动。那张卡在那个正对面的自己的主要怪兽区域特殊召唤。'),
(51786039, 'Nebula Dragon', '星云龙 奈瀑拉', '星雲龍ネビュラ', 'Effect Monster', 'Dragon', 'LIGHT', 8, 2000, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡的这张卡和手卡1只龙族·8星怪兽给对方观看才能发动。那2只守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。这个效果的发动后，直到回合结束时自己不是光·暗属性的龙族怪兽不能召唤·特殊召唤。 ②：把墓地的这张卡除外，以自己墓地1只光·暗属性的龙族·4星怪兽为对象才能发动。那只怪兽加入手卡。'),
(94655777, 'Nebulus, Dragon Ruler of Mishaps', '暗征龙－朦胧', '闇征竜－ネビュラス', 'Effect Monster', 'Dragon', 'DARK', 2, 1000, 600, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：把1只龙族或暗属性的怪兽和这张卡从手卡丢弃，以「暗征龙-朦龙」以外的自己的除外状态的2只属性不同的「征龙」怪兽为对象才能发动。那些怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合不能攻击。 ②：把1只龙族或暗属性的怪兽和这张卡从自己墓地除外，以自己墓地1只「凶征龙-食龙」为对象才能发动。那只怪兽特殊召唤。'),
(70084224, 'Neck Hunter', '猎头魔人', '首狩り魔人', 'Normal Monster', 'Fiend', 'DARK', 6, 1750, 1900, '挥舞着大镰刀的恶魔。从大眼睛中还会发出光柱。'),
(48576971, 'Necklace of Command', '与夺之首饰', '与奪の首飾り', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '自己场上这张卡的装备怪兽被战斗破坏，这张卡送去墓地时，选择下面1个效果发动。 ●从卡组抽1张卡。 ●对方随机丢弃1张手卡去墓地。'),
(77700347, 'Necro Defender', '死灵防御者', 'ネクロ・ディフェンダー', 'Effect Monster', 'Fiend', 'DARK', 2, NULL, 800, '自己的主要阶段时，把墓地存在的这张卡从游戏中除外，选择自己场上存在的1只怪兽才能发动。直到下次的对方的结束阶段时，选择的怪兽不会被战斗破坏，选择的怪兽的战斗发生的对自己的战斗伤害变成0。'),
(99000151, 'Necro Fleur', '死之花', '死の花－ネクロ・フルール', 'Effect Monster', 'Plant', 'DARK', 1, NULL, NULL, '①：这张卡被效果破坏送去墓地的场合才能发动。从卡组把1只「时花之魔女」特殊召唤。'),
(81223446, 'Necro Fusion', '死魂结合', '死魂融合', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：从自己墓地把融合怪兽卡决定的融合素材怪兽里侧表示除外，把那1只融合怪兽从额外卡组融合召唤。这个效果特殊召唤的怪兽在这个回合不能攻击。'),
(4906301, 'Necro Gardna', '死灵守卫者', 'ネクロ・ガードナー', 'Effect Monster', 'Warrior', 'DARK', 3, 600, 1300, '①：对方回合把墓地的这张卡除外才能发动。这个回合，对方怪兽的攻击只有1次无效。'),
(44236692, 'Necro Linker', '死灵连接者', 'ネクロ・リンカー', 'Effect Monster', 'Fiend', 'DARK', 2, 600, NULL, '把这张卡解放，选择自己墓地存在的1只名字带有「同调士」的调整发动。选择的怪兽特殊召唤。这个效果特殊召唤的怪兽这个回合不能作为同调素材。'),
(48421595, 'Necro Synchron', '死之同步士', 'ネクロ・シンクロン', 'Tuner Monster', 'Machine', 'DARK', 2, 200, 400, '这个卡名的②③的效果1回合各能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「鲜花同调士」使用。 ②：以这张卡以外的自己场上1只表侧表示怪兽为对象才能发动。那只怪兽的等级直到回合结束时上升2星。 ③：这张卡作为风属性同调怪兽的同调素材送去墓地的场合才能发动。从卡组把1只植物族·1星怪兽特殊召唤。'),
(28297833, 'Necroface', '死灵脸', 'ネクロフェイス', 'Effect Monster', 'Zombie', 'DARK', 4, 1200, 1800, '①：这张卡召唤成功的场合发动。除外的双方的卡全部回到持有者卡组。这张卡的攻击力上升这个效果回到卡组的数量×100。 ②：这张卡被除外的场合发动。双方玩家各自从自身卡组上面把5张卡除外。'),
(26194151, 'Necroid Synchro', '死灵同步', 'ネクロイド・シンクロ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：调整1只和调整以外的怪兽最多2只从自己墓地除外，把持有和除外的怪兽的等级合计相同等级的1只「星尘」同调怪兽从额外卡组当作同调召唤作特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(61454890, 'Necrolancer the Time-lord', '时间魔人 独眼死灵师', '時の魔人 ネクロランサ', 'Normal Monster', 'Spellcaster', 'DARK', 3, 800, 900, '从时空环出来的可以去任何自己想去的地方的独眼魔人。'),
(93860227, 'Necroquip Princess', '优丽的灵镜姬', '優麗なる霊鏡姫', 'Fusion Monster', 'Fiend', 'DARK', 6, 2000, 2000, '有怪兽卡装备的怪兽＋恶魔族怪兽卡 把自己的手卡·场上的上记的卡送去墓地的场合才能特殊召唤。这个卡名的②的效果1回合只能使用1次。 ①：「优丽的灵镜姬」在自己场上只能有1张表侧表示存在。 ②：怪兽为让卡的效果发动而从手卡送去墓地的场合，可以从以下效果选择1个发动。 ●那之内的1只当作攻击力上升500的装备魔法卡使用给这张卡装备。 ●自己抽1张。'),
(18954366, 'Necroquip Prism', '优丽的灵镜', '優麗なる霊鏡', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只4星以下的怪兽为对象才能发动。把持有那只怪兽的等级以下的等级的1只怪兽从手卡特殊召唤。那之后，作为对象的怪兽当作装备卡使用给那只特殊召唤的怪兽装备。只要这个效果把怪兽装备中，装备怪兽的攻击力上升这个效果装备的怪兽的攻击力一半数值。这个回合，自己不能把那张装备卡以及那些同名卡的效果发动。'),
(47355498, 'Necrovalley', '王家长眠之谷', '王家の眠る谷－ネクロバレー', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：场上的「守墓」怪兽的攻击力·守备力上升500。 ②：只要这张卡在场地区域存在，双方不能把墓地的卡除外，对墓地的卡有涉及的效果无效化并且不适用。'),
(56773577, 'Necrovalley Temple', '王家长眠之谷的神殿', 'ネクロバレーの神殿', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要「守墓」怪兽以及「王家长眠之谷」在场上存在，对方场上的怪兽的攻击力·守备力下降500。 ②：自己的场地区域没有卡存在的场合，1回合1次，自己·对方的主要阶段才能发动。从自己的手卡·墓地选1张「王家长眠之谷」发动。 ③：这张卡被对方的效果破坏送去墓地的场合才能发动。从卡组选「王家长眠之谷的神殿」以外的1张「王家长眠之谷」魔法·陷阱卡在自己场上盖放。'),
(37561138, 'Necrovalley Throne', '王家长眠之谷的玉座', 'ネクロバレーの玉座', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。 ●从卡组把1只「守墓」怪兽加入手卡。 ●从手卡把1只「守墓」怪兽召唤。'),
(66570171, 'Necroworld Banshee', '尸界的报丧女妖', '屍界のバンシー', 'Effect Monster', 'Zombie', 'DARK', 4, 1800, 200, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，场地区域的「不死世界」不会被效果破坏，双方不能把那些卡作为效果的对象。 ②：自己·对方回合，把场上·墓地的这张卡除外才能发动。从手卡·卡组把1张「不死世界」发动。'),
(94230224, 'Needle Ball', '针球', 'ニードル・ボール', 'Flip Effect Monster', 'Fiend', 'DARK', 2, 750, 700, '反转：可以支付2000分，对方受到1000分的伤害。'),
(98162242, 'Needle Burrower', '钢针螯', 'ニードルバンカー', 'Effect Monster', 'Machine', 'DARK', 5, 1700, 1700, '这张卡战斗破坏怪兽并将其送去墓地时，对对方基本分造成数值等同于被破坏怪兽等级×500点的伤害。'),
(38411870, 'Needle Ceiling', '尖刺吊顶', 'つり天井', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '全场上的怪兽4只以上存在的场合才能发动。表侧表示的怪兽全部破坏。'),
(17841097, 'Needle Soldier', '针枪手', 'ニードル・ガンナー', 'Effect Monster', 'Machine', 'EARTH', 1, 100, 100, '这张卡为同调素材的同调怪兽向守备表示怪兽攻击时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。'),
(56223084, 'Needle Sunfish', '针弹翻车鱼', 'ハリマンボウ', 'Effect Monster', 'Fish', 'WATER', 3, 1500, 100, '这张卡被送去墓地时，选择对方场上表侧表示存在的1只怪兽发动。选择的对方怪兽的攻击力下降500。'),
(74440056, 'Needle Token', '小仙人掌斗士', 'サボウ・ファイター', 'Token', 'Plant', NULL, NULL, NULL, NULL, NULL),
(38299233, 'Needle Wall', '刺墙', 'ニードル・ウォール', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '自己的准备阶段时投掷1个骰子。对方的主要怪兽区域，这张卡的控制者从右面看起对应的怪兽区的怪兽算1至5，投掷出的数目对应的怪兽破坏。投掷出6的场合再投掷1次。'),
(81843628, 'Needle Worm', '针虫', 'ニードルワーム', 'Flip Effect Monster', 'Insect', 'EARTH', 2, 750, 600, '反转：对方卡组最上面的5张卡送去墓地。'),
(84968490, 'Needlebug Nest', '针虫的巢窟', '針虫の巣窟', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：从自己卡组上面把5张卡送去墓地。'),
(60666820, 'Nefarious Archfiend Eater of Nefariousness', '恶魔吞食者', 'デーモン・イーター', 'Effect Monster', 'Beast', 'EARTH', 4, 1500, 200, '①：「恶魔食魔兽」在自己场上只能有1张表侧表示存在。 ②：自己场上有魔法师族怪兽存在的场合，这张卡可以从手卡特殊召唤。 ③：这张卡在墓地存在的场合，对方结束阶段，以自己场上1只表侧表示怪兽为对象才能发动。那只怪兽破坏，这张卡特殊召唤。'),
(55117418, 'Nega-Ton Corepanel', '能力吸收核心', '能力吸収コア', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '自己场上有名字带有「核成」的怪兽表侧表示存在，自己墓地有「核成兽的钢核」存在的场合才能发动。效果怪兽的效果的发动无效并破坏。'),
(14315573, 'Negate Attack', '攻击无力化', '攻撃の無力化', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击宣言时，以那1只攻击怪兽为对象才能发动。那次攻击无效。那之后，战斗阶段结束。'),
(66675911, 'Nehshaddoll Genius', '星影依 盖尼乌斯', '星なる影 ゲニウス', 'Flip Effect Monster', 'Machine', 'EARTH', 4, 1800, 1000, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡反转的场合，以自己场上1只「影依」怪兽为对象才能发动。那只表侧表示怪兽直到回合结束时不受自身以外的怪兽的效果影响。 ②：这张卡被效果送去墓地的场合，以场上1只效果怪兽为对象才能发动。这个回合，双方不能把那只效果怪兽的场上发动的效果发动。'),
(18189187, 'Neiroy, the Dream Mirror Disciple', '梦魔镜之使徒－涅伊洛', '夢魔鏡の使徒－ネイロイ', 'Effect Monster', 'Fairy', 'LIGHT', 3, 1000, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：场上有「梦魔镜」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。那之后，可以把这张卡变成暗属性。 ②：这张卡用「梦魔镜」怪兽的效果特殊召唤成功的场合发动。场上有「圣光之梦魔镜」存在的场合，可以选对方场上1张魔法·陷阱卡回到持有者手卡。场上有「黯黑之梦魔镜」存在的场合，自己从卡组抽1张，那之后1张手卡回到卡组。'),
(90176467, 'Neiroy, the Dream Mirror Traitor', '梦魔镜之逆徒－涅伊洛', '夢魔鏡の逆徒－ネイロイ', 'Effect Monster', 'Fiend', 'DARK', 3, 1000, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1只「梦魔镜的使徒-涅洛伊」加入手卡。那之后，可以把这张卡变成光属性。 ②：把自己场上1只其他的「梦魔镜」怪兽解放才能发动。从卡组选1只和那只是等级不同的「梦魔镜」怪兽，把1张在选的怪兽有卡名记述的「圣光之梦魔镜」或者「黯黑之梦魔镜」从卡组加入手卡，选的怪兽守备表示特殊召唤。'),
(11021521, 'Neko Mane King', '招财猫王', 'ネコマネキング', 'Effect Monster', 'Beast', 'EARTH', 1, NULL, NULL, '对方回合中，当这张卡被对方的魔法、陷阱或效果怪兽的效果送去墓地时，对方的回合立刻结束。'),
(1761063, 'Nekogal #1', '猫妖精', 'キャッツ・フェアリー', 'Normal Monster', 'Beast', 'EARTH', 3, 1100, 900, '猫精灵。与可爱的身姿相反、敏捷的攻击对方。'),
(43352213, 'Nekogal #2', '猫女郎', 'キャット・レディ', 'Normal Monster', 'Beast-Warrior', 'EARTH', 6, 1900, 2000, '用敏捷的动作躲避攻击、用锋利的钩爪袭击对方。'),
(97211663, 'Nekroz Cycle', '影灵衣的反魂术', '影霊衣の反魂術', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：等级合计直到变成和仪式召唤的怪兽相同为止，把自己的手卡·场上的怪兽解放，从自己的手卡·墓地把1只「影灵衣」仪式怪兽仪式召唤。 ②：自己场上没有怪兽存在的场合，从自己墓地把1只「影灵衣」怪兽和这张卡除外才能发动。从卡组把1张「影灵衣」魔法卡加入手卡。'),
(50596425, 'Nekroz Divinemirror', '影灵衣之神魔镜', '影霊衣の神魔鏡', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段才能发动。等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的怪兽解放或者作为解放的代替而把额外卡组的「影灵衣」怪兽送去墓地，把自己的手卡·除外状态的1只「影灵衣」仪式怪兽仪式召唤。 ②：自己主要阶段，从自己墓地把1只「影灵衣」怪兽和这张卡除外才能发动。从卡组把1张「影灵衣」魔法卡加入手卡。'),
(51124303, 'Nekroz Kaleidoscope', '影灵衣的万华镜', '影霊衣の万華鏡', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：等级合计直到变成和仪式召唤的怪兽相同为止，把自己的手卡·场上1只怪兽解放或者作为解放的代替而把额外卡组1只怪兽送去墓地，从手卡把「影灵衣」仪式怪兽任意数量仪式召唤。 ②：自己场上没有怪兽存在的场合，从自己墓地把1只「影灵衣」怪兽和这张卡除外才能发动。从卡组把1张「影灵衣」魔法卡加入手卡。'),
(14735698, 'Nekroz Mirror', '影灵衣的降魔镜', '影霊衣の降魔鏡', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：等级合计直到变成和仪式召唤的怪兽相同为止，把自己的手卡·场上的怪兽解放或者作为解放的代替而把自己墓地的「影灵衣」怪兽除外，从手卡把1只「影灵衣」仪式怪兽仪式召唤。 ②：自己场上没有怪兽存在的场合，从自己墓地把1只「影灵衣」怪兽和这张卡除外才能发动。从卡组把1张「影灵衣」魔法卡加入手卡。'),
(39468724, 'Nekroz of Areadbhair', '日神炎枪的影灵衣', 'アラドヴァルの影霊衣', 'Ritual Effect Monster', 'Warrior', 'WATER', 10, 3300, 3200, '「影灵衣」仪式魔法卡降临 这张卡若非以只使用除10星以外的怪兽来作的仪式召唤则不能特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡从手卡丢弃才能发动。自己的手卡·场上最多2只「影灵衣」怪兽解放，把那个数量的「影灵衣」卡从卡组送去墓地。 ②：怪兽的效果发动时，把自己的手卡·场上1只怪兽解放才能发动。那个发动无效并除外。'),
(26674724, 'Nekroz of Brionac', '光枪龙的影灵衣', 'ブリューナクの影霊衣', 'Ritual Effect Monster', 'Warrior', 'WATER', 6, 2300, 1400, '「影灵衣」仪式魔法卡降临 这张卡若非以只使用除「光枪龙之影灵衣」以外的怪兽来作的仪式召唤则不能特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡从手卡丢弃才能发动。从卡组把「光枪龙之影灵衣」以外的1只「影灵衣」怪兽加入手卡。 ②：以从额外卡组特殊召唤的场上最多2只怪兽为对象才能发动。那些怪兽回到卡组。'),
(52846880, 'Nekroz of Catastor', '灾难兽的影灵衣', 'カタストルの影霊衣', 'Ritual Effect Monster', 'Dragon', 'WATER', 5, 2200, 1200, '「影灵衣」仪式魔法卡降临 这张卡若非以只使用除「灾亡虫之影灵衣」以外的怪兽来作的仪式召唤则不能特殊召唤。这个卡名的①的效果1回合只能使用1次。 ①：把这张卡从手卡丢弃，以自己墓地1只「影灵衣」怪兽为对象才能发动。那只怪兽特殊召唤。 ②：自己的「影灵衣」怪兽和从额外卡组特殊召唤的怪兽进行战斗的伤害步骤开始时发动。那只怪兽破坏。'),
(99185129, 'Nekroz of Clausolas', '辉剑鸟的影灵衣', 'クラウソラスの影霊衣', 'Ritual Effect Monster', 'Warrior', 'WATER', 3, 1200, 2300, '「影灵衣」仪式魔法卡降临 这张卡不用仪式召唤不能特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡从手卡丢弃才能发动。从卡组把1张「影灵衣」魔法·陷阱卡加入手卡。 ②：自己·对方回合，以从额外卡组特殊召唤的场上1只表侧表示怪兽为对象才能发动。直到回合结束时，那只怪兽的攻击力变成0，效果无效化。'),
(88240999, 'Nekroz of Decisive Armor', '决战兵器的影灵衣', 'ディサイシブの影霊衣', 'Ritual Effect Monster', 'Dragon', 'WATER', 10, 3300, 2300, '「影灵衣」仪式魔法卡降临 这张卡若非以只使用除10星以外的怪兽来作的仪式召唤则不能特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方回合，把这张卡从手卡丢弃，以自己场上1只「影灵衣」怪兽为对象才能发动。那只怪兽的攻击力·守备力直到回合结束时上升1000。 ②：以对方场上1张里侧表示卡为对象才能发动。那张卡破坏并除外。'),
(74122412, 'Nekroz of Gungnir', '天枪龙的影灵衣', 'グングニールの影霊衣', 'Ritual Effect Monster', 'Spellcaster', 'WATER', 7, 2500, 1700, '「影灵衣」仪式魔法卡降临 这张卡若非以只使用除7星以外的怪兽来作的仪式召唤则不能特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方回合，把这张卡从手卡丢弃，以自己场上1只「影灵衣」怪兽为对象才能发动。那只怪兽在这个回合不会被战斗·效果破坏。 ②：自己·对方回合，从手卡丢弃1张「影灵衣」卡，以场上1张卡为对象才能发动。那张卡破坏。'),
(13408726, 'Nekroz of Metaltron', '梅塔特隆的影灵衣', 'メタトロンの影霊衣', 'Pendulum Effect Ritual Monster', 'Wyrm', 'LIGHT', 9, 2500, 3000, '「影灵衣」仪式魔法卡降临 这张卡若非以只使用除9星以外的怪兽来作的仪式召唤则不能特殊召唤。这个卡名的①的怪兽效果1回合只能使用1次。 ①：自己·对方的主要阶段，以对方场上1只表侧表示怪兽为对象才能发动。这张卡直到结束阶段除外，作为对象的怪兽除外。 ②：自己的「影灵衣」怪兽战斗破坏的怪兽不去墓地而除外。'),
(21105106, 'Nekroz of Sophia', 'sophia的影灵衣', 'sophiaの影霊衣', 'Ritual Effect Monster', 'Spellcaster', 'LIGHT', 11, 3600, 3400, '「影灵衣」仪式魔法卡降临 这张卡若非以使用各自种族不同的自己场上3只怪兽来作的从手卡的仪式召唤则不能特殊召唤。 ①：自己·对方的主要阶段1，从手卡把这张卡和1张「影灵衣」魔法卡丢弃才能发动。那次阶段内，对方不能从额外卡组把怪兽特殊召唤。 ②：这张卡仪式召唤时才能发动（这个效果发动的回合，自己不能把其他怪兽通常召唤·特殊召唤）。这张卡以外的双方的场上·墓地的卡全部除外。'),
(52068432, 'Nekroz of Trishula', '三叉龙的影灵衣', 'トリシューラの影霊衣', 'Ritual Effect Monster', 'Warrior', 'WATER', 9, 2700, 2000, '「影灵衣」仪式魔法卡降临 这张卡若非以只使用除9星以外的怪兽来作的仪式召唤则不能特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：自己场上的「影灵衣」怪兽为对象的魔法·陷阱·怪兽的效果发动时，把这张卡从手卡丢弃才能发动。那个发动无效。 ②：这张卡仪式召唤时才能发动。对方的手卡·场上·墓地的卡各1张合计3张除外（从手卡是随机选）。'),
(89463537, 'Nekroz of Unicore', '尤尼科尔的影灵衣', 'ユニコールの影霊衣', 'Ritual Effect Monster', 'Spellcaster', 'WATER', 4, 2300, 1000, '「影灵衣」仪式魔法卡降临 这张卡不用仪式召唤不能特殊召唤。这个卡名的①的效果1回合只能使用1次。 ①：把这张卡从手卡丢弃，以「尤尼科之影灵衣」以外的自己墓地1张「影灵衣」卡为对象才能发动。那张卡加入手卡。 ②：只要这张卡在怪兽区域存在，从额外卡组特殊召唤的表侧表示怪兽的效果无效化。'),
(25857246, 'Nekroz of Valkyrus', '瓦尔基鲁斯的影灵衣', 'ヴァルキュルスの影霊衣', 'Ritual Effect Monster', 'Spellcaster', 'WATER', 8, 2900, 1700, '「影灵衣」仪式魔法卡降临 这张卡若非以只使用除8星以外的怪兽来作的仪式召唤则不能特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：对方怪兽的攻击宣言时，从自己墓地把1张「影灵衣」卡除外，把这张卡从手卡丢弃才能发动。那次攻击无效。那之后，战斗阶段结束。 ②：自己主要阶段才能发动。自己的手卡·场上最多2只怪兽解放，自己抽出那个数量。'),
(45666710, 'Nemeses Adrastea', '星义之执行者', '星義の執行者', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己墓地的怪兽以及除外的自己怪兽之中以1只「星义」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的原本等级是11星以上的怪兽在这个回合不能把效果发动。'),
(72090076, 'Nemeses Corridor', '星义・绿廊', 'ネメシス・コリドー', 'Effect Monster', 'Thunder', 'WIND', 4, 1900, 600, '这个卡名的①②的效果1回合各能使用1次。 ①：以「星义绿廊兽」以外的除外的1只自己怪兽为对象才能发动。这张卡从手卡特殊召唤，作为对象的怪兽回到卡组。 ②：以「星义绿廊兽」以外的除外的1只自己的「星义」怪兽为对象才能发动。那只怪兽加入手卡。'),
(19211362, 'Nemeses Flag', '星义・标旗', 'ネメシス・フラッグ', 'Effect Monster', 'Pyro', 'FIRE', 2, 1100, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：以「星义旗舰兽」以外的除外的1只自己怪兽为对象才能发动。这张卡从手卡特殊召唤，作为对象的怪兽回到卡组。 ②：自己主要阶段才能发动。从卡组把「星义旗舰兽」以外的1只「星义」怪兽加入手卡。'),
(44440058, 'Nemeses Keystone', '星义・基石', 'ネメシス・キーストーン', 'Effect Monster', 'Rock', 'EARTH', 1, 700, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以「星义关键兽」以外的除外的1只自己怪兽为对象才能发动。这张卡从手卡特殊召唤，作为对象的怪兽回到卡组。 ②：这张卡被除外的回合的结束阶段才能发动。这张卡加入手卡。'),
(46606977, 'Nemeses Umbrella', '星义・护伞', 'ネメシス・アンブレラ', 'Effect Monster', 'Aqua', 'WATER', 3, 1500, 400, '这个卡名的①②的效果1回合各能使用1次。 ①：以「星义伞护兽」以外的除外的1只自己怪兽为对象才能发动。这张卡从手卡特殊召唤，作为对象的怪兽回到卡组。 ②：以「星义伞护兽」以外的自己墓地1只「星义」怪兽为对象才能发动。那只怪兽加入手卡。'),
(43944080, 'Nemleria Dream Defender - Couette', '妮梦雷莉娅的守梦者－库艾特', 'ネムレリアの夢守り－クエット', 'Effect Monster', 'Beast', 'LIGHT', 10, 2000, 2500, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己的额外卡组有表侧表示的灵摆怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：自己的额外卡组有表侧表示的「梦见之妮穆蕾莉娅」存在，自己场上的「妮穆蕾莉娅」卡为对象的效果由对方发动时，从额外卡组把1张里侧表示的卡里侧表示除外才能发动。那个发动无效。'),
(17550376, 'Nemleria Dream Defender - Oreiller', '妮梦雷莉娅的守梦者－欧雷埃', 'ネムレリアの夢守り－オレイエ', 'Effect Monster', 'Beast', 'LIGHT', 10, 2500, 2000, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己的额外卡组有表侧表示的灵摆怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：自己的额外卡组有表侧表示的「梦见之妮穆蕾莉娅」存在的场合，从额外卡组把1张里侧表示的卡里侧表示除外才能发动。这张卡的攻击力直到回合结束时上升对方场上的怪兽数量×500。这个效果在对方回合也能发动。'),
(52382379, 'Nemleria Dream Devourer - Reveil', '妮梦雷莉娅的食梦者－雷贝', 'ネムレリアの夢喰い－レヴェイユ', 'Effect Monster', 'Beast', 'DARK', 10, 2500, 2500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在的场合，把「梦见之妮穆蕾莉娅」以外的额外卡组3张卡里侧除外才能发动（这个效果发动的回合，自己不是灵摆怪兽不能从额外卡组特殊召唤）。这张卡特殊召唤。 ②：从自己的手卡·场上（表侧表示）把这张卡以外的1只兽族·10星怪兽送去墓地才能发动。从卡组把1张「妮穆蕾莉娅」陷阱卡在自己场上盖放。'),
(57296396, 'Nemleria Louve', '妮梦雷莉娅・梦之狼', 'ネムレリア・ルーヴ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡·卡组把1只「妮穆蕾莉娅」怪兽或兽族·10星怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽在结束阶段回到手卡。 ②：把墓地的这张卡除外，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力·守备力直到回合结束时下降自己的除外状态的里侧的卡数量×100。'),
(33499794, 'Nemleria Repeter', '妮梦雷莉娅・回笼', 'ネムレリア・レペッテ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己场上有其他的「妮穆蕾莉娅」卡存在的场合，可以把「梦见之妮穆蕾莉娅」以外的额外卡组的卡的以下数量里侧除外，那个效果发动。 ●1张：从自己墓地把1张「妮穆蕾莉娅」卡加入手卡。 ●2张：这个回合，自己受到的全部伤害变成一半。 ●3张：自己场上1只兽族·10星怪兽送去墓地，对方场上的全部表侧表示怪兽的效果直到回合结束时无效。'),
(90963488, 'Nemuriko', '睡眠之子', '眠り子', 'Normal Monster', 'Spellcaster', 'DARK', 3, 800, 700, '孩子被梦魔所操控永远沉睡着不再醒来。'),
(49563947, 'Neo Aqua Madoor', '新水魔道士', 'ネオアクア・マドール', 'Normal Monster', 'Spellcaster', 'WATER', 6, 1200, 3000, '支配水的魔法师的真正姿态。制造绝对无法破坏的巨大冰墙守备攻击。'),
(56532353, 'Neo Blue-Eyes Ultimate Dragon', '真青眼究极龙', '真青眼の究極竜', 'Fusion Monster', 'Dragon', 'LIGHT', 12, 4500, 3800, '「青眼白龙」＋「青眼白龙」＋「青眼白龙」 这个卡名的①的效果1回合可以使用最多2次。 ①：融合召唤的这张卡攻击的伤害步骤结束时，自己场上没有其他的表侧表示卡存在的场合，从额外卡组把1只「青眼」融合怪兽送去墓地才能发动。这张卡可以继续攻击。 ②：自己场上的「青眼」怪兽为对象的魔法·陷阱·怪兽的效果发动时，把墓地的这张卡除外才能发动。那个发动无效并破坏。'),
(16587243, 'Neo Bug', '新虫', 'ネオバグ', 'Normal Monster', 'Insect', 'EARTH', 4, 1800, 1700, '据说是从异星来的巨大昆虫型怪兽。集体行动捕捉目标。'),
(65156847, 'Neo Flamvell Garuda', '新炎狱金翅鸟', 'ネオフレムベル・ガルーダ', 'Effect Monster', 'Pyro', 'FIRE', 3, 1200, 1800, '自己的结束阶段时，这张卡以外的名字带有「炎狱」的怪兽在自己场上表侧表示存在的场合，选择对方墓地存在的1张卡从游戏中除外。'),
(2377034, 'Neo Flamvell Hedgehog', '新炎狱刺猬', 'ネオフレムベル・ヘッジホッグ', 'Tuner Monster', 'Pyro', 'FIRE', 3, 800, 200, '这张卡被战斗破坏的场合，选择对方墓地存在的1张卡从游戏中除外。场上存在的这张卡被卡的效果破坏的场合，选择自己墓地存在的「新炎狱刺猬」以外的1只守备力200以下的炎属性怪兽加入手卡。'),
(816427, 'Neo Flamvell Lady', '新炎狱女郎', 'ネオフレムベル・レディ', 'Effect Monster', 'Pyro', 'FIRE', 4, 1600, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡把1只炎属性怪兽送去墓地，以对方墓地1张卡为对象才能发动。那张卡除外。这个效果在对方回合也能发动。 ②：这张卡已在怪兽区域存在的状态，从对方墓地有卡被除外的场合才能发动。从卡组把「新炎狱女郎」以外的1只守备力200以下的炎属性怪兽送去墓地。'),
(66378485, 'Neo Flamvell Origin', '新炎狱火源', 'ネオフレムベル・オリジン', 'Tuner Monster', 'Pyro', 'FIRE', 2, 500, 200, '自己场上有「新炎狱火源」以外的名字带有「炎狱」的怪兽表侧表示存在，对方墓地存在的卡是3张以下的场合，这张卡可以从手卡特殊召唤。'),
(91554542, 'Neo Flamvell Sabre', '新炎狱剑士', 'ネオフレムベル・サーベル', 'Effect Monster', 'Pyro', 'FIRE', 4, 1500, 200, '对方墓地存在的卡是4张以下的场合，这张卡的攻击力上升600。对方墓地存在的卡是8张以上的场合，这张卡的攻击力下降300。'),
(39761138, 'Neo Flamvell Shaman', '新炎狱萨满', 'ネオフレムベル・シャーマン', 'Effect Monster', 'Pyro', 'FIRE', 3, 1700, 200, '自己墓地有名字带有「炎狱」的怪兽3只以上存在，这张卡战斗破坏对方怪兽的场合，选择对方墓地存在的1张卡从游戏中除外。这个效果的发动时对方墓地没有魔法卡存在的场合，再给与对方基本分500分伤害。'),
(12632096, 'Neo Galaxy-Eyes Cipher Dragon', '超银河眼光波龙', '超銀河眼の光波龍', 'XYZ Monster', 'Dragon', 'LIGHT', 9, 4500, 3000, '9星怪兽×3 ①：这张卡有「光波」卡在作为超量素材的场合，得到以下效果。 ●1回合1次，把这张卡最多3个超量素材取除才能发动。选取除数量的对方场上的表侧表示怪兽，那些控制权直到结束阶段得到。这个效果得到控制权的怪兽的效果无效化，攻击力变成4500，卡名当作「超银河眼光波龙」使用。这个效果的发动后，直到回合结束时这张卡以外的自己怪兽不能直接攻击。'),
(39272762, 'Neo Galaxy-Eyes Photon Dragon', '超银河眼光子龙', '超銀河眼の光子龍', 'XYZ Monster', 'Dragon', 'LIGHT', 8, 4500, 3000, '8星怪兽×3 「银河眼光子龙」作为素材让这张卡超量召唤成功时，这张卡以外的场上表侧表示存在的卡的效果无效。1回合1次，把这张卡1个超量素材取除才能发动。对方场上的超量素材全部取除，这个回合这张卡的攻击力上升取除数量×500的数值。并且，这个回合这张卡在同1次的战斗阶段中可以作出最多有取除数量的攻击。'),
(45885288, 'Neo Kaiser Glider', '新帝王翔风龙', 'ネオ・カイザー・グライダー', 'Effect Monster', 'Dragon', 'LIGHT', 6, 2400, 2200, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡把这张卡和1只怪兽丢弃，以自己墓地1只龙族通常怪兽为对象才能发动。那只怪兽特殊召唤。 ②：这张卡被送去墓地的场合才能发动。对方场上的全部怪兽的攻击力直到回合结束时下降500。'),
(54332792, 'Neo Kaiser Sea Horse', '真帝王海马', 'ネオ・カイザー・シーホース', 'Tuner Monster', 'Dragon', 'LIGHT', 4, 1700, 1650, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己场上有「青眼白龙」存在的场合才能发动。这张卡从手卡特殊召唤。 ②：以自己场上1只光属性调整为对象才能发动。那只怪兽的等级上升或下降1星。 ③：这张卡从场上送去墓地的场合才能发动。除「新帝王海马」外的1只「青眼」怪兽或者1只有「青眼白龙」的卡名记述的怪兽从卡组送去墓地。'),
(42015635, 'Neo Space', '新宇空间', 'ネオスペース', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '「元素英雄 新宇侠」以及用「元素英雄 新宇侠」作为融合素材的融合怪兽的攻击力上升500。用「元素英雄 新宇侠」作为融合素材的融合怪兽在结束阶段时可以不发动回到卡组效果。'),
(85840608, 'Neo Space Connector', '新宇空间连结者', 'ネオスペース・コネクター', 'Effect Monster', 'Warrior', 'LIGHT', 4, 800, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤成功时才能发动。从手卡·卡组把1只「新空间侠」怪兽或者「元素英雄 新宇侠」守备表示特殊召唤。 ②：把这张卡解放，以自己墓地1只「新空间侠」怪兽或者「元素英雄 新宇侠」为对象才能发动。那只怪兽守备表示特殊召唤。'),
(19594506, 'Neo Space Pathfinder', '新宇空间引导者', 'ネオスペース・コンダクター', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1800, 800, '把这张卡从手卡丢弃去墓地。把自己的卡组或者墓地存在的1张「新宇宙」加入手卡。'),
(95493471, 'Neo Super Quantal Mech King Blaster Magna', '真超级量子机神王 轰闪惊天煌', '真超量機神王ブラスター・マグナ', 'Link Monster', 'Machine', 'LIGHT', NULL, 2500, NULL, '包含「超级量子」怪兽的效果怪兽2只以上 这个卡名的③的效果1回合只能使用1次。 ①：连接召唤的这张卡不会被对方的效果破坏。 ②：每次有同名卡不在自己场上存在的「超级量子」超量怪兽从额外卡组往这张卡所连接区特殊召唤发动。自己从卡组抽1张。 ③：这张卡所连接区的超量怪兽被战斗或者对方的效果破坏的场合才能发动。原本属性和那只超量怪兽相同的1只「超级量子」怪兽从卡组特殊召唤。'),
(50930991, 'Neo the Magic Swordsman', '魔法剑士 尼奥', '魔法剣士ネオ', 'Normal Monster', 'Spellcaster', 'LIGHT', 4, 1700, 1000, '精通武术和剑的奇特魔法师。在异空间旅行着。'),
(12510878, 'Neo-Parshath, the Sky Paladin', '天空勇士 尼奥珀耳修斯', '天空勇士ネオパーシアス', 'Effect Monster', 'Fairy', 'LIGHT', 7, 2300, 2000, '①：这张卡可以把自己场上1只「天空骑士 珀耳修斯」解放从手卡特殊召唤。 ②：场上有「天空的圣域」存在，自己基本分比对方多的场合，这张卡的攻击力·守备力上升那个相差数值。 ③：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ④：这张卡给与对方战斗伤害的场合发动。自己从卡组抽1张。'),
(54959865, 'Neo-Spacian Air Hummingbird', '新空间侠·天空蜂鸟', 'N・エア・ハミングバード', 'Effect Monster', 'Winged Beast', 'WIND', 3, 800, 600, '对方每有1张手卡，自己回复500基本分。这个效果1回合只能使用1次。'),
(17955766, 'Neo-Spacian Aqua Dolphin', '新空间人 水波海豚', 'N・アクア・ドルフィン', 'Effect Monster', 'Warrior', 'WATER', 3, 600, 800, '①：1回合1次，丢弃1张手卡才能发动。把对方手卡确认，从那之中选1只怪兽。持有选的怪兽的攻击力以上的攻击力的怪兽在自己场上存在的场合，选的怪兽破坏，给与对方500伤害。那以外的场合，自己受到500伤害。'),
(43237273, 'Neo-Spacian Dark Panther', '新空间人 漆黑猎豹', 'N・ブラック・パンサー', 'Effect Monster', 'Beast', 'DARK', 3, 1000, 500, '①：1回合1次，以对方场上1只表侧表示怪兽为对象才能发动。直到结束阶段，这张卡得到和那只怪兽的原本的卡名·效果相同的卡名·效果。'),
(89621922, 'Neo-Spacian Flare Scarab', '新空间侠·火焰甲虫', 'N・フレア・スカラベ', 'Effect Monster', 'Insect', 'FIRE', 3, 500, 500, '这张卡的攻击力上升对方场上的魔法·陷阱卡数量×400的数值。'),
(17732278, 'Neo-Spacian Glow Moss', '新空间侠·光辉青苔', 'N・グロー・モス', 'Effect Monster', 'Plant', 'LIGHT', 3, 300, 900, '这张卡进行战斗的场合，对方抽1张卡。这个效果抽到的卡给双方确认，这张卡得到那张卡的种类的以下效果。 ●怪兽卡：这个回合的战斗阶段结束。 ●魔法卡：这张卡可以直接攻击对方玩家。 ●陷阱卡：这张卡变成守备表示。'),
(80344569, 'Neo-Spacian Grand Mole', '新空间人 大地鼹鼠', 'N・グラン・モール', 'Effect Monster', 'Rock', 'EARTH', 3, 900, 300, '①：这张卡和对方怪兽进行战斗的伤害步骤开始时才能发动。那只对方怪兽和这张卡回到持有者手卡。'),
(78734254, 'Neo-Spacian Marine Dolphin', '新空间侠·海洋海豚', 'N・マリン・ドルフィン', 'Fusion Monster', 'Warrior', 'WATER', 4, 900, 1100, '这个卡名在规则上也当作「新空间侠·水波海豚」使用。这张卡用「新空间侠界限」的效果才能特殊召唤。 ①：1回合1次，丢弃1张手卡才能发动。把对方手卡确认，从那之中选1只怪兽。持有选的怪兽的攻击力以上的攻击力的怪兽在自己场上存在的场合，选的怪兽破坏，给与对方500伤害。'),
(13857930, 'Neo-Spacian Twinkle Moss', '新空间侠·闪烁青苔', 'N・ティンクル・モス', 'Fusion Monster', 'Plant', 'LIGHT', 4, 500, 1100, '这张卡名在规则上也当作「新空间侠·光辉青苔」使用。这张卡用「新空间侠界限」的效果才能特殊召唤。这张卡进行战斗的场合，自己抽1张卡。这个效果抽到的卡给双方确认，这张卡得到那张卡的种类的以下效果。 ●怪兽卡：这个回合的战斗阶段结束。 ●魔法卡：这张卡可以直接攻击对方玩家。 ●陷阱卡：这张卡变成守备表示。'),
(47274077, 'Neos Force', '新宇之力', 'ネオス・フォース', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「元素英雄 新宇侠」才能装备。装备怪兽的攻击力上升800。装备怪兽战斗破坏怪兽送去墓地时，给与对方基本分破坏怪兽的攻击力数值的伤害。结束阶段时把这张卡加入卡组洗切。'),
(14088859, 'Neos Fusion', '新宇结合', 'ネオス・フュージョン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从自己的手卡·卡组·场上把融合怪兽卡决定的融合素材怪兽送去墓地，把只以包含「元素英雄 新宇侠」的怪兽2只为素材的那1只融合怪兽无视召唤条件从额外卡组特殊召唤。这张卡的发动后，直到回合结束时自己不能把怪兽特殊召唤。 ②：需以「元素英雄 新宇侠」为融合素材的自己场上的融合怪兽被战斗·效果破坏的场合或者因自身的效果回到额外卡组的场合，可以作为代替把墓地的这张卡除外。'),
(5126490, 'Neos Wiseman', '新宇贤人', 'ネオス・ワイズマン', 'Effect Monster', 'Spellcaster', 'LIGHT', 10, 3000, 3000, '这张卡不能通常召唤。把自己的怪兽区域的表侧表示的「元素英雄 新宇侠」和「于贝尔」各1只送去墓地的场合才能特殊召唤。 ①：场上的这张卡不会被效果破坏。 ②：这张卡和对方怪兽进行战斗的伤害步骤结束时发动。给与对方那只对方怪兽的攻击力数值的伤害。自己基本分回复那只对方怪兽的守备力的数值。'),
(60226558, 'Nephe Shaddoll Fusion', '魂影依结合', '魂写しの同化', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「影依」怪兽才能装备。宣言1个属性才能把这张卡发动。这个卡名的②的效果1回合只能使用1次。 ①：装备怪兽变成宣言的属性。 ②：自己主要阶段才能发动。「影依」融合怪兽卡决定的包含这张卡的装备怪兽的融合素材怪兽从自己的手卡·场上送去墓地，把那1只融合怪兽从额外卡组融合召唤。'),
(46518210, 'Nephilabyss, the Ogdoadic Overlord', '溟界神－涅斐尔邃渊', '溟界神－ネフェルアビス', 'Effect Monster', 'Reptile', 'DARK', 10, 2200, 3100, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在墓地存在的状态，从自己或对方的手卡·卡组有怪兽被送去墓地的场合才能发动。这张卡特殊召唤。这个效果的发动后，直到下个回合的结束时自己不是爬虫类族怪兽不能特殊召唤。 ②：这张卡是已从墓地特殊召唤的场合，以「溟界神-涅斐尔阿比斯」以外的自己墓地1只怪兽为对象才能发动。那只怪兽特殊召唤。'),
(87054946, 'Nephthys, the Sacred Flame', '焰凰神－奈芙蒂斯', '焔凰神－ネフティス', 'Link Monster', 'Winged Beast', 'FIRE', NULL, 2400, NULL, '包含仪式怪兽的怪兽2只以上 ①：这张卡得到作为这张卡的连接素材的仪式怪兽数量的以下效果。 ●1只以上：这张卡不会被战斗破坏。 ●2只以上：这张卡的攻击力上升1200，不会被效果破坏。 ●3只：这张卡的攻击力上升1200，不会成为效果的对象。 ②：只要这张卡在额外怪兽区域存在，对方不能选择主要怪兽区域的「奈芙提斯」怪兽作为攻击对象。'),
(50669347, 'Nephthys, the Sacred Preserver', '守护神－奈芙蒂斯', '守護神－ネフティス', 'Link Monster', 'Winged Beast', 'FIRE', NULL, 1200, NULL, '「奈芙提斯」怪兽2只 这个卡名的效果1回合只能使用1次。 ①：这张卡是已连接召唤的场合，可以从以下效果选择1个发动。 ●从卡组把1只鸟兽族·8星怪兽加入手卡。那之后，可以从自己墓地选1张仪式魔法卡加入手卡。 ●选这张卡所连接区1只「奈芙提斯」怪兽破坏，从自己墓地选原本卡名和那只怪兽不同的1只「奈芙提斯」怪兽效果无效特殊召唤。'),
(21565445, 'Neptabyss, the Atlantean Prince', '海皇子 尼普邃渊', '海皇子 ネプトアビス', 'Effect Monster', 'Sea Serpent', 'WATER', 1, 800, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从卡组把「海皇子 尼普深渊王」以外的1只「海皇」怪兽送去墓地才能发动。从卡组把「海皇子 尼普深渊王」以外的1张「海皇」卡加入手卡。 ②：这张卡为让水属性怪兽的效果发动而被送去墓地的场合，以「海皇子 尼普深渊王」以外的自己墓地1只「海皇」怪兽为对象发动。那只怪兽特殊召唤。'),
(53589300, 'Nerva the Power Patron of Creation', '创狱神 涅瓦', '創獄神ネルヴァ', 'Fusion Monster', 'Illusion', 'EARTH', 10, 3300, 3300, '「神艺」怪兽×3 自己对「创狱神 涅瓦」1回合只能有1次特殊召唤。这张卡用融合召唤以及以下方法才能从额外卡组特殊召唤。 ●把种族不同的自己场上3只怪兽解放的场合可以守备表示特殊召唤。 ①：只要场地区域有卡存在，这张卡不会被效果破坏。 ②：1回合1次，自己把「神艺」怪兽的效果发动时才能发动。那个效果变成「对方场上的卡全部破坏」。'),
(19505896, 'Nettles', '杂草', 'ウィード', 'Tuner Monster', 'Plant', 'EARTH', 2, 1200, 400, '场上表侧表示存在的这张卡被破坏的场合，可以作为代替把自己场上表侧表示存在的这张卡以外的1只植物族怪兽破坏。'),
(84640866, 'Network Trap Hole', '电网落穴', '電網の落とし穴', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方从卡组·墓地把怪兽特殊召唤时才能发动。那些怪兽里侧表示除外。'),
(43845801, 'Neutron Blast', '究极爆裂弹', 'アルティメット・バースト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只融合召唤的「青眼究极龙」为对象才能发动。这个回合，那只怪兽在同1次的战斗阶段中可以作3次攻击，那只怪兽攻击的场合，对方直到伤害步骤结束时魔法·陷阱·怪兽的效果不能发动。'),
(73413514, 'Neverending Nightmare Absorber', '梦幻吸收体', '夢幻吸収体', 'Effect Monster', 'Fairy', 'WATER', 2, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：对方把手卡·墓地·除外状态的怪兽的效果发动的场合才能发动。这张卡从手卡·墓地特殊召唤。这个效果特殊召唤的这张卡在结束阶段破坏。 ②：只要这张卡在怪兽区域存在，每次对方把怪兽的效果发动，这张卡的攻击力上升1000。'),
(56787189, 'New Frontier', '开放的大地', '開かれし大地', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：对方把仪式·融合·同调·超量·连接怪兽特殊召唤的场合，可以从以下效果选择1个发动（这个卡名的以下效果1回合各能选择1次）。 ●把1只「阿不思的落胤」或者有那个卡名记述的怪兽从卡组加入手卡。 ●把1只「阿不思的落胤」或者有那个卡名记述的怪兽从手卡特殊召唤。'),
(62314831, 'New World - Amritara', '新世坏・阿弥利都罗', '新世壊＝アムリターラ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '场上有「维萨斯-斯塔弗罗斯特」存在的场合才能把这张卡发动。 ①：1回合1次，自己场上的怪兽因战斗·效果而破坏，被送去墓地的场合或者被除外的场合，可以从以下效果选择1个发动。 ●那之内的1只在自己场上守备表示特殊召唤。 ●场上1只调整的攻击力上升那之内的1只的攻击力一半数值。 ●那之内的1只回到卡组，自己抽1张。 ●这张卡回到卡组，从自己墓地把1张场地魔法卡加入手卡。'),
(58019984, 'New World Formation', '新世坏成劫', '新世壊成劫', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以有「维萨斯-斯塔弗罗斯特」的卡名记述的自己墓地1张魔法·陷阱卡为对象才能发动。那张卡在自己场上盖放。把速攻魔法·陷阱卡盖放的场合，那张卡在盖放的回合也能发动。 ②：把墓地的这张卡除外，以除「新世坏成劫」外的有「维萨斯-斯塔弗罗斯特」的卡名记述的自己墓地3张魔法·陷阱卡为对象才能发动。那些卡回到卡组。'),
(85407683, 'New World Stars', '星罗的新世坏', '星満ちる新世壊', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只要自己场上有「维萨斯-斯塔弗罗斯特」存在，自己怪兽在1回合各有1次不会被战斗破坏。 ②：自己场上有「维萨斯-斯塔弗罗斯特」存在的场合，自己结束阶段，以自己墓地1只怪兽为对象才能发动。那只怪兽回到卡组。自己场上有同调怪兽调整存在的场合，也能不回到卡组加入手卡。'),
(10807219, 'Newbee!', '新异蜜蜂！', 'ニュービー！', 'Effect Monster', 'Insect', 'LIGHT', 2, NULL, NULL, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己墓地有攻击力和守备力是0的怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡从手卡特殊召唤的场合才能发动。以下效果各能适用。 ●「菜鸟新蜂族！」以外的自己墓地1只昆虫族·光属性怪兽加入手卡。 ●自己的墓地·除外状态的1张陷阱卡回到卡组最上面或最下面。'),
(4335645, 'Newdoria', '阴间领路人', 'ニュードリュア', 'Effect Monster', 'Fiend', 'DARK', 4, 1200, 800, '①：这张卡被战斗破坏送去墓地的场合，以场上1只怪兽为对象发动。那只怪兽破坏。'),
(81913510, 'NEX', '新空间侠界限', 'NEX', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上表侧表示存在的1只名字带有「新空间侠」的怪兽送去墓地，当作和送去墓地的卡同名卡使用的1只4星怪兽从额外卡组特殊召唤。'),
(74414885, 'NEXT', '新宇空间扩张', 'NEXT', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。自己场上没有卡存在的场合，这张卡的发动从手卡也能用。 ①：从自己的手卡·墓地选「新空间侠」怪兽以及「元素英雄 新宇侠」任意数量守备表示特殊召唤（同名卡最多1张）。这个效果特殊召唤的怪兽的效果无效化。只要这个效果特殊召唤的怪兽在自己场上表侧表示存在，自己不是融合怪兽不能从额外卡组特殊召唤。'),
(7076131, 'Next to be Lost', '消失的后者', 'ロスト・ネクスト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只怪兽。从自己卡组选1张和选择的卡同名的卡送去墓地。'),
(54862960, 'Ni-Ni the Mirror Mikanko', '镜之御巫 琼琼', '鏡の御巫ニニ', 'Effect Monster', 'Spellcaster', 'WATER', 3, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡没有装备卡装备的场合，这张卡的战斗发生的对自己的战斗伤害变成0，有装备的场合，这张卡不会被战斗破坏，这张卡的战斗发生的对自己的战斗伤害由对方代受。 ②：对方回合，这张卡有装备卡装备的场合，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的控制权直到结束阶段得到。'),
(27204311, 'Nibiru, the Primal Being', '原始生命态 尼比鲁', '原始生命態ニビル', 'Effect Monster', 'Rock', 'LIGHT', 11, 3000, 600, '这个卡名的效果1回合只能使用1次。 ①：对方把5只以上的怪兽召唤·特殊召唤的自己·对方回合的主要阶段才能发动。自己·对方场上的表侧表示怪兽尽可能解放，这张卡从手卡特殊召唤。那之后，在对方场上把1只「原始生命态衍生物」（岩石族·光·11星·攻/守?）特殊召唤。这衍生物的攻击力·守备力变成这个效果解放的怪兽的原本的攻击力·守备力各自合计数值。'),
(49275969, 'Nidhogg, Generaider Boss of Ice', '冰之创王 尼多格', '氷の王 ニードヘッグ', 'Effect Monster', 'Wyrm', 'WATER', 9, 2100, 2600, '这个卡名的②的效果1回合只能使用1次。 ①：「冰界王战 尼德霍格王」在自己场上只能有1只表侧表示存在。 ②：对方把怪兽特殊召唤之际，把自己场上1只「王战」怪兽或者幻龙族怪兽解放才能发动。那次特殊召唤无效，那些怪兽破坏。'),
(16226786, 'Night Assailant', '深渊的暗杀者', '深淵の暗殺者', 'Flip Effect Monster', 'Fiend', 'DARK', 3, 200, 500, '①：这张卡反转的场合，以对方场上1只怪兽为对象发动。那只对方怪兽破坏。 ②：这张卡从手卡送去墓地的场合，以「深渊的暗杀者」以外的自己墓地1只反转怪兽为对象发动。那只怪兽加入手卡。'),
(89882100, 'Night Beam', '夜间摄击', 'ナイト・ショット', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以对方场上盖放的1张魔法·陷阱卡为对象才能发动。盖放的那张卡破坏。对方不能对应这张卡的发动把作为对象的卡发动。'),
(88724332, 'Night Dragolich', '夜龙巫妖', 'ナイト・ドラゴリッチ', 'Effect Monster', 'Wyrm', 'DARK', 4, 1700, NULL, '①：只要这张卡在怪兽区域存在，幻龙族以外的从卡组·额外卡组特殊召唤的攻击表示怪兽变成守备表示。 ②：只要这张卡在怪兽区域存在，幻龙族以外的从卡组·额外卡组特殊召唤的怪兽的守备力下降那个原本守备力数值。'),
(51126152, 'Night Express Knight', '深夜急行骑士 夜行特快骑兵', '深夜急行騎士ナイト・エクスプレス・ナイト', 'Effect Monster', 'Machine', 'EARTH', 10, 3000, 3000, '这张卡不能从卡组特殊召唤。 ①：这张卡可以不用解放作召唤。 ②：这张卡的①的方法召唤的这张卡的原本攻击力变成0。'),
(42560034, 'Night Flight', '夜之逃飞行', '夜の逃飛行', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以自己场上1只表侧表示怪兽为对象才能发动。那只表侧表示怪兽回到持有者手卡。这个回合，双方不能把这个效果加入手卡的卡以及那些同名卡的效果发动。'),
(78402798, 'Night Lizard', '蜥蜴骑士', 'ナイト・リザード', 'Normal Monster', 'Aqua', 'WATER', 4, 1150, 1300, '守护着大会、被绿色的鳞片包住身体的蜥蜴战士。'),
(2191144, 'Night Papilloperative', '夜蝶刺客', 'ナイト・バタフライ・アサシン', 'XYZ Monster', 'Warrior', 'DARK', 4, 2600, 2000, '4星怪兽×3 1回合1次，把这张卡1个超量素材取除才能发动。这张卡的攻击力上升场上的超量素材数量×300的数值。'),
(20295753, 'Night Sword Serpent', '夜刀蛇巳', '夜刀蛇巳', 'Effect Monster', 'Reptile', 'WATER', 4, 500, 600, '这个卡名的效果1回合只能使用1次。 ①：这张卡被效果送去墓地的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(49826746, 'Night Wing Sorceress', '黑翼的魔术师', '黒翼の魔術師', 'Effect Monster', 'Spellcaster', 'WIND', 3, 1300, 1200, '只要这张卡在自己场上表侧表示存在，这张卡的控制者可以在「爆裂模式」盖放的回合发动。'),
(3779493, 'Night''s End Administrator', '夜尽管理者', 'ナイトエンド・アドミニストレーター', 'Synchro Monster', 'Spellcaster', 'LIGHT', 6, 2300, 1400, '「夜尽巫师」＋调整以外的怪兽1只以上 这个卡名的②的效果1回合只能使用1次。 ①：这张卡特殊召唤成功的场合或者自己场上有这张卡以外的魔法师族怪兽特殊召唤的场合，以对方墓地1张卡为对象才能发动。那张卡除外。 ②：怪兽区域的这张卡被战斗或者对方的效果破坏的场合，以自己墓地1只4星以下的魔法师族怪兽为对象才能发动。那只怪兽特殊召唤。'),
(36107810, 'Night''s End Sorcerer', '夜尽巫师', 'ナイトエンド・ソーサラー', 'Tuner Monster', 'Spellcaster', 'DARK', 2, 1300, 400, '①：这张卡特殊召唤成功时，以对方墓地最多2张卡为对象才能发动。那些卡除外。'),
(58143852, 'Nightmare Apprentice', '幻惑见习魔术使', '幻惑の見習い魔術師', 'Effect Monster', 'Illusion', 'DARK', 6, 2000, 1700, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡可以丢弃1张手卡，从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把「幻惑之见习魔术师」以外的1只幻想魔族怪兽加入手卡。 ③：这张卡和怪兽进行战斗的场合，那2只不会被那次战斗破坏。'),
(42956964, 'Nightmare Archfiend Token', '梦魇恶魔群', 'ナイトメア・デーモンズ', 'Token', 'Fiend', NULL, NULL, NULL, NULL, NULL),
(42956963, 'Nightmare Archfiends', '梦魇恶魔群', 'ナイトメア・デーモンズ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上1只怪兽解放才能发动。在对方场上把3只「梦魇恶魔衍生物」（恶魔族·暗·6星·攻/守2000）攻击表示特殊召唤。「梦魇恶魔衍生物」被破坏时那控制者受到每1只800伤害。'),
(25224340, 'Nightmare Hands', '幻惑的操手', '幻惑の操手', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从卡组把1只幻想魔族怪兽送去墓地。 ②：自己场上有5星以上的幻想魔族怪兽存在的场合，自己主要阶段把墓地的这张卡除外，以对方墓地1只怪兽为对象才能发动。那只怪兽在自己场上特殊召唤。这个效果特殊召唤的怪兽在下个回合的结束阶段除外。'),
(59290628, 'Nightmare Horse', '梦魇马', 'ナイトメア・ホース', 'Effect Monster', 'Zombie', 'DARK', 2, 500, 400, '这张卡在对方场上存在怪兽的状态下也能对对方进行直接攻击。'),
(40221691, 'Nightmare Magician', '幻惑的魔术士', '幻惑の魔術師', 'Effect Monster', 'Illusion', 'DARK', 7, 2500, 2000, '①：这张卡和怪兽进行战斗的场合，那2只不会被那次战斗破坏。 ②：这张卡和对方怪兽进行战斗的伤害步骤结束时才能发动。得到那只对方怪兽的控制权。 ③：1回合1次，这张卡以外的怪兽攻击的伤害步骤开始时才能发动。场上1张卡破坏。'),
(65261141, 'Nightmare Pain', '梦魇苦痛', 'ナイトメア・ペイン', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己主要阶段才能发动。自己的手卡·场上（表侧表示）1只暗属性怪兽破坏，除「噩梦之苦痛」外的1只「于贝尔」或者1张有那个卡名记述的卡从卡组加入手卡。 ②：只要自己场上有「于贝尔」怪兽存在，可以攻击的对方怪兽必须向「于贝尔」怪兽作出攻击。 ③：自己的「于贝尔」怪兽的战斗发生的对自己的战斗伤害由对方代受。'),
(81306586, 'Nightmare Penguin', '梦魇企鹅', 'ペンギン・ナイトメア', 'Effect Monster', 'Aqua', 'WATER', 4, 900, 1800, '①：这张卡反转的场合，以对方场上1张卡为对象发动。那张对方的卡回到持有者手卡。 ②：只要这张卡在怪兽区域存在，自己场上的水属性怪兽的攻击力上升200。'),
(88643173, 'Nightmare Scorpion', '梦魇蝎', 'ナイトメア・スコーピオン', 'Normal Monster', 'Insect', 'EARTH', 3, 900, 800, '造出恶梦，并在呻吟的时候用四条有毒的尾巴刺向敌人。'),
(300203002, 'Nightmare Sonic Blast!', NULL, NULL, 'Skill Card', 'Rex', NULL, NULL, NULL, NULL, NULL),
(93729896, 'Nightmare Throne', '梦魇王座', 'ナイトメア・スローン', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，以下效果可以适用。 ●从卡组选1只攻击力和守备力是0的恶魔族怪兽加入手卡或破坏。 ②：1回合1次，自己场上的表侧表示的「于贝尔」怪兽因效果从场上离开的场合才能发动。原本等级比那之内的1只要高1星或低1星的1只「于贝尔」怪兽从自己的卡组·墓地·除外状态加入手卡。那之后，可以把那只怪兽无视召唤条件特殊召唤。'),
(54704216, 'Nightmare Wheel', '拷问车轮', '拷問車輪', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '以对方场上1只怪兽为对象才能把这张卡发动。 ①：只要这张卡在魔法与陷阱区域存在，作为对象的怪兽不能攻击，也不能作表示形式的变更。那只怪兽从场上离开时这张卡破坏。 ②：自己准备阶段发动。给与对方500伤害。这个效果在作为对象的怪兽在怪兽区域存在的场合进行发动和处理。'),
(30138615, 'Nightmare-Eyes Restrict', '幻惑眼纳祭魔', 'ナイトメア・アイズ・サクリファイス', 'Fusion Monster', 'Illusion', 'DARK', 1, NULL, NULL, '种族不同的恶魔族·幻想魔族·魔法师族怪兽×2 这个卡名的①的效果1回合只能使用1次。 ①：这张卡特殊召唤的场合或者这张卡进行战斗的战斗阶段结束时才能发动。对方场上1只怪兽当作装备魔法卡使用给这张卡装备。 ②：这张卡的攻击力上升这张卡的效果装备的怪兽的攻击力数值。 ③：这张卡和怪兽进行战斗的场合，那2只不会被那次战斗破坏。 ④：对方怪兽不能向其他怪兽攻击。'),
(58775978, 'Nightmare''s Steelcage', '噩梦之铁栏', '悪夢の鉄檻', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡发动后继续留在场上，用对方回合计算的2回合后的对方结束阶段破坏。 ①：只要这张卡在魔法与陷阱区域存在，怪兽不能攻击。'),
(66569334, 'Nightmell the Dark Bonder', '恶醒师 奈特魅尔特', '悪醒師ナイトメルト', 'Effect Monster', 'Psychic', 'WIND', 4, 1500, 1500, '这个卡名的效果1回合只能使用1次。 ①：把自己场上1只怪兽解放才能发动。和那只怪兽是原本卡名不同并是原本的种族·属性·等级·攻击力·守备力相同的1只怪兽从卡组特殊召唤。把从额外卡组特殊召唤的怪兽解放发动的场合，也能从额外卡组选这个效果特殊召唤的怪兽。'),
(79519259, 'Nightwinged Cleric', '夜翼祭司', 'ナイトウィング・プリースト', 'Synchro Monster', 'Spellcaster', 'WIND', 8, 2500, 2500, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。从自己的手卡·卡组·墓地把1张「爆裂模式」在自己场上盖放。这个效果盖放的卡在盖放的回合也能发动。 ②：丢弃1张手卡才能发动。从卡组选有「爆裂模式」的卡名记述的1只怪兽加入手卡或特殊召唤。这个回合，自己不是同调怪兽不能从额外卡组特殊召唤。'),
(24701235, 'Nikitama', '和魂', '和魂', 'Spirit Monster', 'Fairy', 'LIGHT', 4, 800, 1800, '这张卡不能特殊召唤。 ①：这张卡召唤·反转的回合，自己在通常召唤外加上只有1次，自己主要阶段可以把1只灵魂怪兽召唤。 ②：这张卡召唤·反转的回合的结束阶段发动。这张卡回到持有者手卡。 ③：这张卡被送去墓地的场合发动。自己从卡组抽1张。这个效果在自己场上有灵魂怪兽存在的场合进行发动和处理。'),
(88686573, 'Nimble Angler', '迅捷鮟鱇', '素早いアンコウ', 'Effect Monster', 'Fish', 'WATER', 2, 600, 100, '这张卡从手卡·卡组送去墓地的场合，可以从卡组把「迅捷鮟鱇」以外的最多2只3星以下的名字带有「迅捷」的怪兽特殊召唤。'),
(68353324, 'Nimble Beaver', '迅捷海狸', '素早いビーバー', 'Effect Monster', 'Beast', 'WATER', 2, 400, 200, '①：这张卡召唤成功时才能发动。从自己的卡组·墓地选1只3星以下的「迅捷」怪兽特殊召唤。'),
(46384403, 'Nimble Manta', '迅捷蝠鲼', '素早いマンタ', 'Effect Monster', 'Fish', 'WATER', 2, 800, 100, '场上存在的这张卡被卡的效果送去墓地时，可以从自己卡组把「迅捷蝠鲼」任意数量特殊召唤。'),
(22567609, 'Nimble Momonga', '迅捷飞鼠', '素早いモモンガ', 'Effect Monster', 'Beast', 'EARTH', 2, 1000, 100, '这张卡被战斗破坏送去墓地时，自己回复1000基本分。并且可以再从卡组把「迅捷鼯鼠」任意数量里侧守备表示特殊召唤。'),
(57844634, 'Nimble Musasabi', '迅捷飞鼠', '素早いムササビ', 'Effect Monster', 'Beast', 'EARTH', 2, 800, 100, '这张卡被战斗破坏送去墓地时，给与对方基本分500分伤害。并且可以再从自己卡组把「迅捷飞鼠」任意数量在对方场上表侧攻击表示特殊召唤。这张卡不能为上级召唤而解放。'),
(2843014, 'Nimble Sunfish', '迅捷翻车鱼', '素早いマンボウ', 'Effect Monster', 'Fish', 'WATER', 2, 1000, 100, '这张卡被战斗破坏送去墓地时，从自己卡组把1只鱼族怪兽送去墓地。那之后，可以从自己卡组把1只「迅捷翻车鱼」特殊召唤。'),
(11987744, 'Nin-Ken Dog', '忍犬 奇狗', '忍犬ワンダードッグ', 'Normal Monster', 'Beast-Warrior', 'WIND', 4, 1800, 1000, '忍术攀登到顶峰的狗忍者。通过严格的修行，变得可以使用拟人化的忍术。'),
(8660395, 'Ninaruru, the Magistus Glass Goddess', '伟魔女神 结晶之宁阿鲁鲁', '結晶の女神ニンアルル', 'XYZ Monster', 'Rock', 'EARTH', 4, 1800, 2400, '魔法师族4星怪兽×2 这个卡名的①③的效果1回合各能使用1次。 ①：把这张卡1个超量素材取除，以自己墓地1只4星以上的魔法师族怪兽为对象才能发动。那只怪兽加入手卡。 ②：有这张卡装备的怪兽在同1次的战斗阶段中最多2次可以向怪兽攻击。 ③：这张卡装备中的场合，以自己的魔法与陷阱区域1张「大贤者」卡和对方场上1张魔法·陷阱卡为对象才能发动。那些卡破坏。'),
(57831349, 'Nine Pillars of Yang Zing', '龙星的九支', '竜星の九支', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：自己场上有「龙星」卡存在，怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效，那张卡回到持有者卡组。那之后，选这张卡以外的自己场上1张「龙星」卡破坏。'),
(28981598, 'Nine-Lives Cat', '九魂猫', '九魂猫', 'XYZ Monster', 'Zombie', 'EARTH', 9, 900, 3300, '9星怪兽×2 这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，从墓地特殊召唤的自己场上的其他怪兽不会成为对方的效果的对象。 ②：把这张卡1个超量素材取除，以自己墓地1只9星怪兽或者对方墓地1只怪兽为对象才能发动。那只怪兽在自己场上特殊召唤。'),
(27198001, 'Nine-Tailed Fox', '九尾狐', '九尾の狐', 'Effect Monster', 'Zombie', 'FIRE', 6, 2200, 2000, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在的场合，把自己场上2只怪兽解放才能发动。这张卡特殊召唤。 ②：从墓地特殊召唤的这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ③：这张卡被战斗·效果破坏送去墓地的场合才能发动。在自己场上把2只「狐衍生物」（不死族·炎·2星·攻/守500）特殊召唤。'),
(30194529, 'Ningirsu the World Chalice Warrior', '星杯战士 宁吉尔苏', '星杯戦士ニンギルス', 'Link Monster', 'Warrior', 'EARTH', NULL, 2500, NULL, '连接怪兽2只以上 这个卡名的①的效果1回合只能使用1次。 ①：这张卡连接召唤成功的场合发动。自己从卡组抽出这张卡所连接区的「星杯」怪兽的数量。 ②：1回合1次，自己主要阶段才能发动。选自己以及对方场上的卡各1张送去墓地。 ③：这张卡从场上送去墓地的场合才能发动。从手卡把1只「星杯」怪兽特殊召唤。'),
(95027497, 'Ninja Grandmaster Hanzo', '忍者头领 半藏', '忍者マスター HANZO', 'Effect Monster', 'Warrior', 'DARK', 4, 1800, 1000, '①：这张卡召唤成功时才能发动。从卡组把1张「忍法」卡加入手卡。 ②：这张卡反转召唤·特殊召唤成功时才能发动。从卡组把「忍者头领 半藏」以外的1只「忍者」怪兽加入手卡。'),
(37354507, 'Ninja Grandmaster Saizo', '忍者头领 才藏', '忍者マスター SAIZO', 'Link Monster', 'Warrior', 'LIGHT', NULL, 2000, NULL, '「忍者」怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡所连接区有怪兽存在，这张卡不会成为攻击对象，也不会成为对方的效果的对象。 ②：自己主要阶段才能发动。从卡组选1张「忍法」魔法·陷阱卡在自己场上盖放。'),
(4041838, 'Ninja Grandmaster Sasuke', '忍者头领 佐助', '忍者マスター SASUKE', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1800, 1000, '这张卡攻击表侧守备表示的怪兽的场合，不进入伤害计算，那只怪兽直接破坏。'),
(79324191, 'Ninjitsu Art Notebook', '隐密忍法帖', '隠密忍法帖', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，从手卡把1只「忍者」怪兽送去墓地才能发动。从卡组选「隐密忍法帖」以外的1张「忍法」魔法·陷阱卡在自己场上盖放。'),
(95545183, 'Ninjitsu Art Notebook of Mystery', '异谭的忍法帖', '異譚の忍法帖', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：对方场上有卡存在的场合才能发动。「异谭的忍法帖」以外的「忍法」魔法·陷阱卡以及「忍者」怪兽各最多1张从自己的卡组·墓地选出在自己场上盖放（从卡组·墓地各只能有最多1张盖放）。 ②：盖放的这张卡被送去墓地的场合，以场上1只表侧表示怪兽为对象才能发动。那只怪兽变成里侧守备表示。'),
(68038375, 'Ninjitsu Art of Dancing Leaves', '忍法 落叶舞', '忍法 落葉舞', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己·对方场上1只「忍者」怪兽或者里侧守备表示怪兽为对象才能把这张卡发动。那只怪兽解放，从卡组把1只「忍者」怪兽特殊召唤。这张卡从场上离开时那只怪兽送去墓地。 ②：这张卡表侧表示存在的场合，以自己的魔法与陷阱区域1张「忍法」永续魔法·永续陷阱卡为对象才能发动。那张卡回到持有者手卡。'),
(89628781, 'Ninjitsu Art of Decoy', '忍法 空蝉之术', '忍法 空蝉の術', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '选择自己场上的名字有「忍者」字样的1只怪兽才能发动。只要这张卡在场上存在，被选择的怪兽不会被战斗破坏（伤害计算适用）。'),
(50766506, 'Ninjitsu Art of Duplication', '忍法 分身之术', '忍法 分身の術', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：把自己场上1只「忍者」怪兽解放才能把这张卡发动。等级合计最多到解放的怪兽的等级以下为止，从卡组选「忍者」怪兽任意数量各以表侧攻击表示或者里侧守备表示特殊召唤。这张卡从场上离开时那些怪兽全部破坏。'),
(63626024, 'Ninjitsu Art of Mirage-Transformation', '忍法 妖变化之术', '忍法 妖変化の術', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己场上1只「忍者」怪兽解放，以对方墓地1只怪兽为对象才能把这张卡发动。那只怪兽在自己场上特殊召唤。这个效果特殊召唤的怪兽在这张卡表侧表示存在期间，也当作「忍者」怪兽使用。这张卡从场上离开时那只怪兽送去墓地。'),
(68441986, 'Ninjitsu Art of Mosquito Marching', '蚊学忍法・军蚊行军', '蚊学忍法・軍蚊マーチ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡把最多2只4星以下的昆虫族怪兽特殊召唤（把2只特殊召唤的场合必须是相同等级）。 ②：自己场上有「No.2 蚊学忍者 影蚊」存在的场合，把墓地的这张卡除外，以最多有自己场上的昆虫族怪兽数量的对方场上的表侧表示怪兽为对象才能发动。给那些怪兽放置1个幻觉指示物。有幻觉指示物放置的怪兽的效果无效化。'),
(13629812, 'Ninjitsu Art of Shadow Sealing', '忍法 影缝之术', '忍法 影縫いの術', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '把自己场上1只名字带有「忍者」的怪兽解放才能发动。选择对方场上1只怪兽从游戏中除外。只要那只怪兽从游戏中除外中，那个怪兽卡区域不能使用。这张卡从场上离开时，这个效果除外的怪兽以相同表示形式回到原本的怪兽卡区域。'),
(90200789, 'Ninjitsu Art of Super-Transformation', '忍法 超变化之术', '忍法 超変化の術', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '选择自己场上1只名字带有「忍者」的怪兽和对方场上表侧表示存在的1只怪兽发动。选择的怪兽送去墓地，把1只那个等级合计以下的龙族·恐龙族·海龙族怪兽从自己卡组往自己场上特殊召唤。这张卡从场上离开时，那只怪兽从游戏中除外。'),
(70861343, 'Ninjitsu Art of Transformation', '忍法 变化之术', '忍法 変化の術', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：把自己场上1只表侧表示的「忍者」怪兽解放才能把这张卡发动。把持有解放的怪兽的等级＋3以下的等级的1只兽族·鸟兽族·昆虫族怪兽从手卡·卡组特殊召唤。这张卡从场上离开时那只怪兽破坏。'),
(32939238, 'Ninjitsu Art Tool - Iron Digger', '忍法装具 铁土龙', '忍法装具 鉄土竜', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：装备怪兽的攻击力上升500，也当作「忍者」怪兽使用。 ②：从自己墓地把1只「忍者」怪兽除外，以场上1张卡为对象才能发动。那张卡破坏。 ③：这张卡从场上送去墓地的场合，以除外的1只自己的「忍者」怪兽为对象才能发动。那只怪兽加入手卡或里侧守备表示特殊召唤。'),
(80896940, 'Nirvana High Paladin', '涅槃的超魔导剑士', '涅槃の超魔導剣士', 'Synchro Pendulum Effect Monster', 'Spellcaster', 'DARK', 10, 3300, 2500, '调整＋调整以外的同调怪兽1只以上 这张卡同调召唤的场合，可以用自己场上1只灵摆召唤的灵摆怪兽当作调整使用。 ①：这张卡用灵摆召唤的灵摆怪兽为调整作同调召唤成功的场合，以自己墓地1张卡为对象才能发动。那张卡加入手卡。 ②：这张卡战斗破坏对方怪兽时才能发动。对方基本分变成一半。 ③：怪兽区域的这张卡被战斗·效果破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(96182448, 'Nitro Synchron', '氮素同步士', 'ニトロ・シンクロン', 'Tuner Monster', 'Machine', 'FIRE', 2, 300, 100, '这张卡被名字带有「氮素」的同调怪兽的同调召唤使用送去墓地的场合，从自己卡组抽1张卡。'),
(23842445, 'Nitro Unit', '硝化装置', 'ニトロユニット', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '对方场上的怪兽才能装备。装备怪兽被战斗破坏送去墓地时，给与对方基本分装备怪兽攻击力数值的伤害。'),
(18013090, 'Nitro Warrior', '氮素战士', 'ニトロ・ウォリアー', 'Synchro Monster', 'Warrior', 'FIRE', 7, 2800, 1800, '「氮素同调士」＋调整以外的怪兽1只以上 只要这张卡在场上表侧表示存在，自己回合自己把魔法卡发动的场合，这张卡的攻击力只在那个回合的伤害计算时只有1次上升1000。此外，这张卡的攻击破坏对方怪兽的伤害计算后才能发动。选择对方场上表侧守备表示存在的1只怪兽变成攻击表示，向那只怪兽只再1次可以继续攻击。'),
(49204190, 'Nitwit Outwit', '奇策', '奇策', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：从手卡丢弃1只怪兽，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力下降因为这个效果发动而丢弃的怪兽的攻击力数值。'),
(7805359, 'Niwatori', '喔喔', 'コケ', 'Normal Monster', 'Winged Beast', 'EARTH', 3, 900, 800, '把敌人整个吞下，并消化作为能量来补充自己。'),
(60306104, 'No Entry!!', '进入禁止！No Entry！！', '進入禁止！No Entry！！', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '场上存在的攻击表示怪兽全部变成守备表示。'),
(300302015, 'No More Mrs. Nice Mai!', NULL, NULL, 'Skill Card', 'Mai Valentine', NULL, NULL, NULL, NULL, NULL),
(300302068, 'No One Suspects the Dark Scorpion Gang!', NULL, NULL, 'Skill Card', 'Don Zaloog', NULL, NULL, NULL, NULL, NULL),
(83438826, 'Noble Arms - Arfeudutyr', '圣剑 阿隆戴特', '聖剣アロンダイト', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '战士族怪兽才能装备。这个卡名的③的效果1回合只能使用1次。 ①：「圣剑 阿隆戴特」在自己场上只能有1张表侧表示存在。 ②：1回合1次，以对方场上盖放的1张卡为对象才能发动。装备怪兽的攻击力下降500，那张盖放的对方的卡破坏。 ③：场上的表侧表示的这张卡被破坏送去墓地的场合，以自己场上1只战士族「圣骑士」怪兽为对象才能发动。那只自己怪兽把这张卡装备。'),
(23562407, 'Noble Arms - Caliburn', '圣剑 石中剑', '聖剣カリバーン', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '战士族怪兽才能装备。装备怪兽的攻击力上升500。此外，1回合1次，自己可以回复500基本分。场上表侧表示存在的这张卡被破坏送去墓地的场合，可以选择自己场上1只名字带有「圣骑士」的战士族怪兽把这张卡装备。「圣剑 石中剑」的这个效果1回合只能使用1次。此外，「圣剑 石中剑」在自己场上只能有1张表侧表示存在。'),
(41359411, 'Noble Arms - Clarent', '圣剑 克拉伦特', '聖剣クラレント', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '战士族怪兽才能装备。这个卡名的③的效果1回合只能使用1次。 ①：「圣剑 克拉伦特」在自己场上只能有1张表侧表示存在。 ②：1回合1次，支付500基本分才能发动。这个回合，装备怪兽可以直接攻击。 ③：场上的表侧表示的这张卡被破坏送去墓地的场合，以自己场上1只战士族「圣骑士」怪兽为对象才能发动。那只自己的战士族「圣骑士」怪兽把这张卡装备。'),
(46008667, 'Noble Arms - Excaliburn', '圣剑 断钢湖中剑', '聖剣 EX－カリバーン', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「圣骑士」怪兽才能装备。「圣剑 断钢湖中剑」的②的效果1回合只能使用1次。 ①：装备怪兽不会成为对方的效果的对象。 ②：自己主要阶段把墓地的这张卡除外，以自己场上1只「圣骑士」超量怪兽为对象才能发动。和那只自己怪兽卡名不同的1只「圣骑士」超量怪兽在作为对象的怪兽上面重叠当作超量召唤从额外卡组特殊召唤。这个效果在这张卡送去墓地的回合不能发动。'),
(14745409, 'Noble Arms - Gallatin', '圣剑 加拉廷', '聖剣ガラティーン', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '战士族怪兽才能装备。这个卡名的③的效果1回合只能使用1次。 ①：「圣剑 加拉廷」在自己场上只能有1张表侧表示存在。 ②：装备怪兽的攻击力上升1000，每次自己准备阶段下降200。 ③：场上的表侧表示的这张卡被破坏送去墓地的场合，以自己场上1只战士族「圣骑士」怪兽为对象才能发动。那只自己的战士族「圣骑士」怪兽把这张卡装备。'),
(25807544, 'Noble Arms Museum', '大圣剑博物馆', '大聖剣博物館', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：自己场上的战士族·炎属性怪兽的攻击力上升500。 ②：1回合1次，支付1200基本分才能发动。从卡组把「大圣剑博物馆」以外的1张「圣剑」卡加入手卡。 ③：这张卡的②的效果适用的回合1次，以自己的魔法与陷阱区域1张「圣骑士」怪兽卡为对象才能发动。那张卡特殊召唤。自己场上没有「焰圣骑士帝-查理」存在的状态把这个效果发动过的场合，直到回合结束时自己不是战士族怪兽不能特殊召唤。'),
(7452945, 'Noble Arms of Destiny', '天命之圣剑', '天命の聖剣', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '战士族怪兽才能装备。这个卡名的③的效果1回合只能使用1次。 ①：「天命之圣剑」在自己场上只能有1张表侧表示存在。 ②：装备怪兽1回合只有1次不会被战斗·效果破坏。 ③：场上的表侧表示的这张卡被破坏送去墓地的场合，以自己场上1只战士族「圣骑士」怪兽为对象才能发动。那只自己的战士族「圣骑士」怪兽把这张卡装备。'),
(92125819, 'Noble Knight Artorigus', '圣骑士 阿托利斯', '聖騎士アルトリウス', 'Normal Monster', 'Warrior', 'LIGHT', 4, 1800, 1800, '属于圣骑士团的聪明青年骑士。仿佛就像受到了引导，闯入了森林之中的他，终于抵达命运的所在。随后，青年迈出了那一大步。 ——这是一切的开端，一段伟大的史诗。'),
(30575681, 'Noble Knight Bedwyr', '圣骑士 贝德维尔', '聖騎士ベディヴィエール', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1600, 1500, '①：这张卡召唤·特殊召唤成功时才能发动。从卡组把1张「圣剑」装备魔法卡送去墓地。 ②：只在这张卡在场上表侧表示存在才有1次，以场上1张「圣剑」装备魔法卡和1只可以把那张卡装备的怪兽为对象才能发动。那张装备魔法卡转移给作为正确对象的那只怪兽。这个效果在对方回合也能发动。'),
(47120245, 'Noble Knight Borz', '圣骑士 鲍斯', '聖騎士ボールス', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1700, 900, '①：这张卡只要在怪兽区域存在，当作通常怪兽使用。 ②：只要这张卡有「圣剑」装备魔法卡装备，这张卡变成当作效果怪兽使用并得到以下效果。 ●这张卡等级上升1星并变成暗属性。 ●自己主要阶段才能发动。从卡组把3张「圣剑」卡给对方观看，对方从那之中随机选1张。那1张卡加入自己手卡，剩余送去墓地。这个卡名的这个效果1回合只能使用1次。'),
(57690191, 'Noble Knight Brothers', '圣骑士三兄弟', '聖騎士の三兄弟', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1200, 2400, '①：这张卡召唤成功时才能发动。从手卡把最多2只「圣骑士」怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是「圣骑士」怪兽不能特殊召唤。 ②：这张卡在自己场上的怪兽是「圣骑士」怪兽3只的场合才能攻击。 ③：1回合1次，以自己墓地的「圣骑士」卡以及「圣剑」卡合计3张为对象才能发动。那3张卡加入卡组洗切。那之后，自己从卡组抽1张。'),
(42472002, 'Noble Knight Custennin', '圣骑士 康尼厄斯', '聖騎士コルネウス', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1000, 2000, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：自己场上有「圣剑」装备魔法卡存在的场合，这张卡可以从手卡特殊召唤。 ②：场上的这张卡为素材作同调·超量·连接召唤的「圣骑士」怪兽得到以下效果。 ●这次特殊召唤成功的场合才能发动。这个回合，自己在通常召唤外加上只有1次，自己主要阶段可以把1只怪兽召唤。这个效果的发动后，直到回合结束时自己不是「圣骑士」怪兽不能从额外卡组特殊召唤。'),
(53550467, 'Noble Knight Drystan', '圣骑士 崔斯坦', '聖騎士トリスタン', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1800, 800, '「圣骑士 崔斯坦」的②的效果1回合只能使用1次。 ①：只要自己场上有这张卡以外的「圣骑士」怪兽存在，对方不能把这张卡以外的自己场上的攻击力未满1800的怪兽作为攻击对象，也不能作为效果的对象。 ②：让这张卡把「圣剑」装备魔法卡装备的场合，以场上1张表侧表示的卡为对象发动。那张表侧表示的卡破坏。'),
(93085839, 'Noble Knight Eachtar', '圣骑士 爱克托·德·马利斯', '聖騎士エクター・ド・マリス', 'Effect Monster', 'Warrior', 'DARK', 5, 1600, 2000, '「圣骑士 爱克托·德·马利斯」的①的效果1回合只能使用1次。 ①：把自己墓地2只「圣骑士」怪兽除外才能发动。这张卡从手卡·墓地特殊召唤。 ②：这张卡为素材的「圣骑士」怪兽的同调召唤·超量召唤不会被无效化，在那次特殊召唤成功时对方不能把魔法·陷阱·怪兽的效果发动。'),
(19680539, 'Noble Knight Gawayn', '圣骑士 高文', '聖騎士ガウェイン', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1900, 500, '自己场上有光属性的通常怪兽存在的场合，这张卡可以从手卡表侧守备表示特殊召唤。'),
(13391185, 'Noble Knight Gwalchavad', '圣骑士 加拉哈德', '聖騎士ガラハド', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1500, 1800, '这张卡只要在场上表侧表示存在，当作通常怪兽使用。只要这张卡有名字带有「圣剑」的装备魔法卡装备，这张卡变成当作效果怪兽使用并得到以下效果。 ●选择自己墓地1只名字带有「圣骑士」的怪兽才能发动。选择的怪兽加入手卡，选自己场上1张名字带有「圣剑」的装备魔法卡破坏。「圣骑士 加拉哈德」的这个效果1回合只能使用1次。'),
(88923963, 'Noble Knight Iyvanne', '圣骑士 伊文', '聖騎士イヴァン', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1700, 1600, '这个卡名的①的效果1回合只能使用1次。 ①：让这张卡把「圣剑」装备魔法卡装备的场合才能发动。在自己场上把1只「圣骑士衍生物」（战士族·光·4星·攻/守1000）特殊召唤。这个效果的发动后，直到回合结束时自己不是「圣骑士」怪兽不能特殊召唤。 ②：只要这张卡有「圣剑」装备魔法卡装备，这张卡以外的自己场上的「圣骑士」怪兽的攻击力上升500。'),
(18426196, 'Noble Knight Joan', '圣骑士 贞德', '聖騎士ジャンヌ', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1900, 1300, '①：这张卡攻击的伤害步骤内，这张卡的攻击力下降300。 ②：这张卡被对方破坏送去墓地的场合，把1张手卡送去墓地，以自己墓地1只4星以下的战士族怪兽为对象才能发动。那只战士族怪兽加入手卡。'),
(59057152, 'Noble Knight Medraut', '圣骑士 莫德雷德', '聖騎士モルドレッド', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1700, 1000, '①：这张卡只要在怪兽区域存在，当作通常怪兽使用。 ②：只要这张卡有「圣剑」装备魔法卡装备，这张卡变成当作效果怪兽使用并得到以下效果。 ●这张卡等级上升1星并变成暗属性。 ●1回合1次，自己场上没有这张卡以外的怪兽存在的场合才能发动。从卡组把「圣骑士 莫德雷德」以外的1只「圣骑士」怪兽守备表示特殊召唤，选自己场上1张装备魔法卡破坏。'),
(5361816, 'Noble Knight Pellinore', '圣骑士 佩里诺尔', '聖騎士ペリノア', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1900, 500, '这个卡名的效果1回合只能使用1次。 ①：以这张卡装备的1张「圣剑」装备魔法卡和对方场上1只表侧表示怪兽为对象才能发动。那些卡破坏。那之后，自己从卡组抽1张。这个效果的发动后，直到回合结束时这张卡不能攻击。');